// k6: ramp up to 200 virtual users with pass criteria
import http from 'k6/http';
import { check } from 'k6';

export const options = {
  stages: [
    { duration: '2m', target: 200 },
    { duration: '5m', target: 200 },
    { duration: '1m', target: 0 },
  ],
  thresholds: {
    http_req_duration: ['p(95)<300'],
    http_req_failed: ['rate<0.01'],
  },
};

export default function () {
  const res = http.get('https://staging.shop.com/products?page=0');
  check(res, { 'status 200': (r) => r.status === 200 });
}

class DiscountProperties {
    @Property
    void discountNeverMakesPriceNegative(@ForAll @BigRange(min = "0", max = "100000") BigDecimal price,
                                         @ForAll @IntRange(min = 0, max = 100) int percent) {
        BigDecimal result = Discount.apply(price, percent);
        assertThat(result).isBetween(BigDecimal.ZERO, price);
    }
}

// WRONG: the same formula on both sides
